WITH `t0` AS (SELECT `tenantId`, `entityId`, `version`, `market_stock_total` FROM `metric_group_ots_component_market_availability` FINAL WHERE `tenantId` = {p0:String}), `t1` AS (SELECT `c`.`entityId` AS `entityId`, `c`.`category` AS `category`, `a`.`market_stock_total` AS `stock` FROM (SELECT `entityId`, `category` FROM `entity_ots_component` WHERE `tenantId` = {p1:String} AND `state` = {p2:String}) AS `c` INNER ALL JOIN (SELECT `m`.`entityId` AS `entityId`, `m`.`market_stock_total` AS `market_stock_total` FROM `t0` AS `m` INNER ALL JOIN (SELECT `tenantId`, `entityId`, max(`version`) AS `version` FROM `t0` GROUP BY `tenantId`, `entityId`) AS `v` ON `m`.`tenantId` = `v`.`tenantId` AND `m`.`entityId` = `v`.`entityId` AND `m`.`version` = `v`.`version`) AS `a` ON `c`.`entityId` = `a`.`entityId`) SELECT `__typedhouse_input`.`__typedhouse_leaf_0` AS `entityId`, `__typedhouse_input`.`__typedhouse_leaf_2` / `__typedhouse_input`.`__typedhouse_leaf_4` * {p3:Float64} AS `share` FROM (SELECT `e`.`entityId` AS `__typedhouse_leaf_0`, `e`.`stock` AS `__typedhouse_leaf_2`, `t`.`stock` AS `__typedhouse_leaf_4` FROM (SELECT `t1`.`entityId`, `t1`.`category`, `t1`.`stock` FROM `t1`) AS `e` INNER ALL JOIN (SELECT ifNull(`__typedhouse_input`.`category`, {p4:String}) AS `category`, sum(`__typedhouse_input`.`stock`) AS `stock` FROM (SELECT `t1`.`entityId`, `t1`.`category`, `t1`.`stock` FROM `t1`) AS `__typedhouse_input` GROUP BY ifNull(`__typedhouse_input`.`category`, {p4:String})) AS `t` ON ifNull(`e`.`category`, {p5:String}) = `t`.`category`) AS `__typedhouse_input`
